mapper.select:
SELECT COUNT(*)
FROM child_parent cp
         INNER JOIN child c ON c.child_id = cp.child_id
WHERE cp.child_id = #{childId}
  AND cp.member_id = #{memberId}
  AND c.status = 'ACTIVE'

SELECT financial_transfer_id
FROM financial_transfer
WHERE idempotency_key = #{idempotencyKey}

mapper.update:
UPDATE financial_account
SET balance = balance - #{amount},
    balance_updated_at = UTC_TIMESTAMP(6)
WHERE financial_account_id = #{accountId}
  AND balance >= #{amount}

UPDATE financial_transfer
SET status = 'SUCCEEDED',
    account_transaction_id = #{debitTransactionId},
    completed_at = #{completedAt}
WHERE financial_transfer_id = #{transferId}
  AND status = 'REQUESTED'

mapper.select:
SELECT ft.financial_transfer_id AS financialTransferId, fg.financial_goal_id AS financialGoalId, fg.title AS goalTitle, ft.amount, ft.transfer_type AS transferType, ft.status, ft.requested_at AS requestedAt, ft.completed_at AS completedAt FROM financial_transfer ft INNER JOIN financial_account dst ON dst.financial_account_id = ft.destination_account_id LEFT JOIN financial_goal_account fga ON fga.financial_account_id = dst.financial_account_id LEFT JOIN financial_goal fg ON fg.financial_goal_id = fga.financial_goal_id WHERE ft.child_id = #{childId}
AND fg.financial_goal_id = #{financialGoalId}
AND ft.status = #{status}
AND ft.requested_at >= #{startDate}
AND ft.requested_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND ft.financial_transfer_id < #{cursorId}
ORDER BY ft.financial_transfer_id DESC LIMIT #{limit}

SELECT ft.financial_transfer_id AS financialTransferId, ft.child_id AS childId, ft.requested_by_member_id AS requestedByMemberId, ft.transfer_type AS transferType, ft.amount, ft.memo, ft.status, ft.failure_code AS failureCode, ft.failure_message AS failureMessage, ft.requested_at AS requestedAt, ft.completed_at AS completedAt,
src.financial_account_id AS sourceAccountId, src.bank_name AS sourceBankName, src.account_name AS sourceAccountName, src.account_number_ciphertext AS sourceAccountNumberCiphertext,
dst.financial_account_id AS destinationAccountId, dst.bank_name AS destinationBankName, dst.account_name AS destinationAccountName, dst.account_number_ciphertext AS destinationAccountNumberCiphertext FROM financial_transfer ft INNER JOIN financial_account src ON src.financial_account_id = ft.source_account_id INNER JOIN financial_account dst ON dst.financial_account_id = ft.destination_account_id WHERE ft.requested_by_member_id = #{memberId}
AND ft.child_id = #{childId}
AND ft.status = #{status}
AND ft.transfer_type = #{transferType}
AND ft.requested_at >= #{startDate}
AND ft.requested_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND ft.financial_transfer_id < #{cursorId}
ORDER BY ft.financial_transfer_id DESC LIMIT #{limit}
